  NAV.forEach(function(domain){domain.children.forEach(function(child){if(!LABELS[child[0]])LABELS[child[0]]=child[1];});});
  var selectedPage='PAGE-004',selectedTab='feedback',selectedReviewProject=null,providerFlowState={};
  var activeMode='UI_CANDIDATE',activeSource='fixture v3';

  function esc(value){return String(value==null?'UNKNOWN':value).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function route(hash){var raw=(hash||'#overview').replace(/^#/,'').split('/').filter(Boolean),parts=[];try{parts=raw.map(decodeURIComponent);}catch(_error){return{view:'overview',id:null};}var view=LABELS[parts[0]]?parts[0]:'overview';return{view:view,id:parts[1]||null,project_id:view==='review'?(parts[1]||null):null,page_id:view==='review'?(parts[2]||null):null,version:view==='review'?(parts[3]||null):null};}
  function link(view,id){return'#'+view+(id?'/'+encodeURIComponent(id):'');}
  function reviewLink(projectId,pageId,version){var out='#review/'+encodeURIComponent(projectId);if(pageId)out+='/'+encodeURIComponent(pageId);if(version)out+='/'+encodeURIComponent(version);return out;}
  function chip(state,label){return'<span class="status-chip state-'+esc(state)+'">'+esc(label||state)+'</span>';}
  function boundary(){return activeMode==='HOSTED_TEST_ONLY'?'<div class="source-banner"><strong>HOSTED · TEST_ONLY</strong><span>事实读取来自服务端同源投影；大模型页仅调用服务端既有受限动作，服务端仍会重验管理员身份、CSRF、目标平台和凭据。</span></div>':'<div class="source-banner"><strong>合成候选</strong><span>页面数据来自 '+esc(activeSource)+'，不连接 Identity、CRM、Finance、安装器或生产任务。所有动作均禁用，不写真实服务。</span></div>';}
