  function progress(value){var width=value.total?Math.round(value.done/value.total*100):0;return'<div class="progress" aria-label="'+value.done+'/'+value.total+' 阶段"><span style="width:'+width+'%"></span></div>'}
  function metric(m){return'<a class="card metric-card metric-link" href="'+esc(m.href)+'"><span class="metric-label">'+esc(m.label)+'</span><div class="metric-value">'+esc(m.value)+'</div><span class="status-chip tone-'+esc(m.tone)+'">'+esc(m.delta)+'</span></a>';}
  function projectRow(p){return'<article class="record-row"><div class="record-main"><a href="'+link('project',p.id)+'"><strong>'+esc(p.name)+'</strong></a><small class="mono">'+esc(p.id)+' · '+esc(p.kind)+'</small>'+progress(p.progress)+'</div><div>'+chip(p.stage,p.stage_label)+'</div><div><small>责任方</small><br>'+esc(p.owner)+'</div><div><small>'+esc(p.updated)+'</small></div><a class="button" href="'+link('project',p.id)+'">查看</a></article>';}
  function projectCard(p){return'<article class="card project-card"><div class="project-top"><div><h3>'+esc(p.name)+'</h3><small class="mono">'+esc(p.id)+'</small></div>'+chip(p.stage,p.stage_label)+'</div><div class="project-meta"><span>客户/归属<b>'+esc(p.customer)+'</b></span><span>当前责任方<b>'+esc(p.owner)+'</b></span><span>下一动作<b>'+esc(p.next_action)+'</b></span><span>UI 版本<b>'+esc(p.ui_version)+'</b></span></div>'+progress(p.progress)+'<a class="button" href="'+link('project',p.id)+'">进入项目</a></article>';}
  function renderOverview(data){var hosted=data.mode==='HOSTED_TEST_ONLY',projects=data.projects.length?data.projects.map(projectRow).join(''):'<div class="callout unknown"><strong>NOT_CONNECTED</strong><span>项目权威源未接入，未填充替代记录。</span></div>',events=data.events.length?data.events.map(function(e){return'<article class="event"><strong>'+esc(e.title)+'</strong><small>'+esc(e.time)+' · '+esc(e.actor)+'</small><div class="mono muted">'+esc(e.ref)+'</div></article>';}).join(''):'<div class="callout unknown"><strong>NONE_FOUND</strong><span>没有可展示的审计事件。</span></div>',scope=hosted?'<section class="card"><div class="card-head"><h2>读取范围</h2>'+chip('READ_ONLY')+'</div><div class="fact-grid">'+fact('数据读取时间',data.observed_at)+fact('源数据时间',data.source_observed_at)+fact('tenant',data.tenant_id)+fact('权限范围','TASK_CENTER_ADMIN / READ_ONLY')+'</div></section>':'';return pageHead('今天需要你关注什么？',hosted?'从服务端 TEST_ONLY 只读投影查看任务；未接业务事实保持 UNKNOWN。':'从项目、执行与证据的同一批合成记录查看工作，不把心跳、ACK 或静态页面冒充完成。',hosted?'':'<a class="button primary" href="#review">进入待审核项目</a>')+boundary()+scope+'<section class="grid metric-grid">'+data.metrics.map(metric).join('')+'</section><section class="two-col grid"><div><div class="section-title"><h2>优先项目</h2><a href="#projects">查看全部</a></div><div class="card flush record-list">'+projects+'</div></div><aside><div class="section-title"><h2>事件与风险</h2></div><div class="card timeline">'+events+'</div></aside></section>';}
  function renderProjects(data){return pageHead('客户与项目','同一项目对象关联需求、页面版本、任务、制品和验收；缺少生产 adapter 时明确 UNKNOWN。','<button class="button primary" data-demo-action="new-project">新建项目（演示）</button>')+boundary()+'<div class="toolbar"><label class="search-field">搜索项目<input id="projectSearch" type="search" placeholder="项目名称或 ID"></label><label>阶段<select id="projectStage"><option value="">全部阶段</option><option value="PENDING_REVIEW">待审核</option><option value="IN_DEVELOPMENT">开发中</option><option value="BLOCKED">阻塞</option></select></label></div><p id="resultSummary" class="muted">'+data.projects.length+' 个合成项目</p><section class="grid three-col" id="projectGrid">'+data.projects.map(projectCard).join('')+'</section><nav class="pagination" aria-label="项目分页"><button class="button" disabled>上一页</button><span>第 1 / 1 页 · SYNTHETIC</span><button class="button" disabled>下一页</button></nav>';}
  function renderProjectsAdmin(data){var meta={producer:'Identity / CRM / Customer Project Center'};return renderProjects(data)+'<section class="grid two-col admin-boundary"><article class="card"><h2>权限范围操作</h2><div class="callout unknown"><strong>SERVER_AUTHORITATIVE</strong><span>服务端 capability 未接入；前端隐藏按钮不构成授权。</span></div><button class="button primary" disabled>新增/变更项目（无 capability）</button></article>'+renderOperationLog(meta)+'</section>';}
  function fact(label,value){return'<div class="fact"><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div>';}
  function renderProject(data,id){var p=data.projects.filter(function(x){return x.id===id;})[0];if(!p)return pageHead('项目不存在','该合成 ID 不存在，未向其他数据源查询。')+'<div class="callout danger">无法定位项目。<a href="#projects">返回项目列表</a></div>';
    var stages=['需求与范围','原型/UI','开发','测试与独审','安装与验收'];
    return'<div class="breadcrumb"><a href="#projects">客户与项目</a><span>/</span><span>'+esc(p.id)+'</span></div>'+pageHead(p.name,p.id+' · '+p.customer,'<a class="button primary" href="'+reviewLink(p.id,p.pages[0]&&p.pages[0].id,p.pages[0]&&p.pages[0].version)+'">打开审核工作区</a><button class="button" data-demo-action="project-more">更多</button>')+boundary()+'<section class="card"><div class="card-head"><div><h2>项目状态</h2><small>版本与责任边界固定展示</small></div>'+chip(p.stage,p.stage_label)+'</div><div class="fact-grid">'+fact('tenant_id',p.tenant_id)+fact('project_id',p.project_id)+fact('ui_version',p.ui_version)+fact('environment',p.environment)+fact('task_id',p.task_id)+fact('attempt_id',p.attempt_id)+fact('commit',p.commit)+fact('artifact_sha',p.artifact_sha)+fact('evidence_ref',p.evidence_ref)+'</div><div class="stage-rail">'+stages.map(function(s,i){var current=i===2;return'<div class="stage'+(current?' current':'')+'"><strong>'+(i+1)+'. '+s+'</strong><small>'+(i<2?'合成已记录':current?'当前候选':'NOT_EXECUTED')+'</small></div>';}).join('')+'</div></section><div class="section-title"><h2>页面与版本</h2><span class="muted">页面确认不等于项目已安装</span></div>'+(p.pages.length?'<section class="card flush record-list">'+p.pages.map(function(x){return'<article class="record-row"><div class="record-main"><strong>'+esc(x.name)+'</strong><small class="mono">'+esc(x.page_id)+' · '+esc(x.ui_version)+'</small></div>'+chip(x.status,x.label)+'<span>'+x.changes+' 项变更</span><span>'+esc(x.previous)+' → '+esc(x.version)+'</span><a class="button" href="'+reviewLink(p.id,x.id,x.version)+'">审核</a></article>';}).join('')+'</section>':'<div class="card"><div class="empty-illustration">∅</div><h3>暂无页面版本</h3><p class="muted">项目 adapter 尚未连接，不能用演示页面填充真实项目。</p></div>')+'<div class="section-title"><h2>原入口兼容</h2></div><div class="legacy-link"><div><strong>旧入口保持不变</strong><small class="mono">'+esc(p.legacy_entry_ref||'NONE_FOUND')+'</small></div><button class="button" data-demo-action="legacy">仅显示引用</button></div>';}
  function renderProjectAdmin(data,id){var html=renderProject(data,id);if(html.indexOf('项目不存在')>=0)return html;return html+'<section class="grid two-col admin-boundary"><article class="card"><h2>权限范围操作</h2><div class="callout unknown"><strong>SERVER_AUTHORITATIVE</strong><span>项目 capability 必须由原服务返回；当前 UNKNOWN。</span></div><button class="button primary" disabled>变更项目（无 capability）</button></article>'+renderOperationLog({producer:'Identity / CRM / Customer Project Center'})+'</section>';}
  function layer(x){return'<article class="layer">'+chip(x.state,x.label)+'<small>'+esc(x.detail)+'</small></article>';}
  function pageTree(project){return'<div class="page-list">'+project.pages.map(function(x){return'<a class="page-item'+(x.id===selectedPage?' active':'')+'" href="'+reviewLink(project.id,x.id,x.version)+'"><strong>'+esc(x.name)+'</strong><small>'+esc(x.id)+' · '+esc(x.version)+'</small>'+chip(x.status,x.label)+'</a>';}).join('')+'</div>';}
  function syntheticPreview(page){if(page.url)return'<div class="preview-frame"><div class="preview-toolbar"><span class="mono">AUTHORIZED_PRIVATE_PREVIEW · '+esc(page.id)+' · '+esc(page.version)+'</span><span>不使用 iframe</span></div><div class="card"><h3>'+esc(page.name)+'</h3><p>在原客户中心认证边界打开精确版本；返回后继续审核。</p><a class="button primary" href="'+esc(page.url)+'" target="_blank" rel="noopener">打开原私有预览</a></div></div>';return'<div class="preview-frame"><div class="preview-toolbar"><span class="mono">SYNTHETIC_PREVIEW · '+esc(page.id)+' · '+esc(page.version)+'</span><span>无 iframe / 无网络</span></div><div class="preview-canvas"><div class="synthetic-page"><div class="synthetic-nav"><span></span><span></span><span></span></div><div class="synthetic-hero"><div><p class="eyebrow">'+esc(page.name)+'</p><div class="placeholder title"></div><div class="placeholder"></div><div class="placeholder short"></div><button class="button primary" data-demo-action="preview">合成主动作</button></div><div class="card"><small>页面状态</small><h3>'+esc(page.label)+'</h3><p class="muted">当前版本：'+esc(page.version)+'</p></div></div><div class="preview-cards"><div></div><div></div><div></div></div></div></div></div>';}
  function reviewPanel(data){var r=data.review;if(selectedTab==='feedback'&&r.authoritative_review){var state=r.authoritative_review,approved=state.state==='DESIGN_APPROVED_TASK_BOUND',history=(state.comments||[]).map(function(x){return'<article class="feedback-item"><strong>评论 · '+esc(x.actor)+'</strong><p>'+esc(x.text)+'</p><small>'+esc(new Date(x.created*1000).toISOString())+'</small></article>';}).concat((state.events||[]).map(function(x){return'<article class="feedback-item"><strong>'+esc(x.kind)+' · '+esc(x.actor)+'</strong><p>'+esc(x.payload&&x.payload.reason||'未记录理由')+'</p><small>'+esc(new Date(x.created*1000).toISOString())+' · '+esc(x.payload&&x.payload.task_id||'NO_TASK')+'</small></article>';})).join('');return'<div class="tab-panel"><div class="callout '+(approved?'success':'unknown')+'"><strong>'+esc(state.state)+'</strong><span>'+(approved?'设计批准已绑定原 Canonical Task；不代表技术 QA、发布或业务验收。':'批准前必须绑定该项目已存在的 Canonical Task。')+'</span></div>'+(state.approval_receipt?'<div class="fact-grid compact">'+fact('task_id',state.approval_receipt.task_id)+fact('event_id',state.approval_receipt.event_id)+fact('record_sha256',state.approval_receipt.record_sha256)+'</div>':'')+(approved?'':'<label>批准理由<textarea id="reviewApprovalReason" rows="4" maxlength="4000" required></textarea></label><button class="button primary" data-review-approve="1" '+(r.task_id==='UNKNOWN'?'disabled':'')+'>明确设计通过并绑定原任务</button>')+'<h3>历史回看</h3>'+(history||'<p class="muted">NONE_FOUND</p>')+'</div>';}if(selectedTab==='feedback')return'<div class="tab-panel">'+r.feedback.map(function(x){return'<article class="feedback-item"><div class="card-head"><strong>'+esc(x.id)+' · '+esc(x.scope)+'</strong>'+chip(x.state)+'</div><p>'+esc(x.text)+'</p><small>'+esc(x.actor)+' · '+esc(x.version)+'</small></article>';}).join('')+'<label>审核意见（仅本地）<textarea id="feedbackDraft" rows="4" placeholder="记录页面、版本和期望变化"></textarea></label><button class="button primary" data-demo-action="save-feedback">保存合成意见</button></div>';
    if(selectedTab==='diff')return'<div class="version-diff"><div class="diff-pane"><strong>上一版 v2.3</strong><div class="diff-line minus">− 安装状态：已完成</div><div class="diff-line">责任方位于折叠区域</div></div><div class="diff-pane"><strong>当前版 v2.3-r2</strong><div class="diff-line plus">+ 安装状态：NOT_EXECUTED</div><div class="diff-line plus">+ 责任方与下一动作首屏显示</div></div></div>';
    return'<div class="tab-panel">'+r.evidence.map(function(x){return'<article class="evidence-item"><div class="card-head"><strong>'+esc(x.kind)+'</strong>'+chip(x.state)+'</div><p class="mono">'+esc(x.ref)+'</p></article>';}).join('')+'</div>';}
  function renderReviewQueue(data){var rows=data.projects.filter(function(p){return p.stage==='PENDING_REVIEW'||p.stage==='BLOCKED'||p.pages.length;});return pageHead('预览与审核队列','先选择项目，再进入绑定 project_id/page_id/ui_version 的审核工作区。')+boundary()+'<div class="toolbar"><label class="search-field">筛选项目<input id="reviewSearch" type="search" placeholder="项目名称或 project_id"></label><label>审核状态<select id="reviewStage"><option value="">全部</option><option value="PENDING_REVIEW">待审核</option><option value="BLOCKED">阻塞</option></select></label></div><section class="grid three-col" id="reviewQueue">'+rows.map(function(p){var first=p.pages[0];return'<article class="card project-card"><div class="project-top"><div><h3>'+esc(p.name)+'</h3><small class="mono">'+esc(p.project_id)+'</small></div>'+chip(p.stage,p.stage_label)+'</div><p>'+esc(p.next_action)+'</p><div class="fact-grid compact">'+fact('tenant_id',p.tenant_id)+fact('ui_version',p.ui_version)+fact('page_id',first?first.page_id:'NONE_FOUND')+fact('evidence_ref',p.evidence_ref)+'</div>'+(first?'<a class="button primary" href="'+reviewLink(p.id,first.id,first.version)+'">进入项目审核</a>':'<button class="button" disabled>页面 NONE_FOUND</button>')+'</article>';}).join('')+'</section>';}
  function renderReview(data,r){if(!r.project_id)return renderReviewQueue(data);var project=data.projects.filter(function(p){return p.id===r.project_id;})[0];if(!project)return pageHead('审核项目不存在','没有跨项目回退；不会展示其他项目的数据。')+boundary()+'<div class="callout danger">project_id '+esc(r.project_id)+' 为 UNKNOWN。<a href="#review">返回审核列表</a></div>';var pages=project.pages;if(!pages.length)return pageHead('项目暂无可审核页面',project.id)+boundary()+'<div class="callout unknown">page_id NONE_FOUND。<a href="#review">返回审核列表</a></div>';var page=pages.filter(function(x){return x.id===(r.page_id||pages[0].id);})[0]||pages[0];selectedPage=page.id;var version=r.version||page.version;var base=data.review;var review=Object.assign({},base,{tenant_id:project.tenant_id,project_id:project.id,page_id:page.id,ui_version:version,environment:project.environment,task_id:project.task_id,attempt_id:project.attempt_id,commit:project.commit,artifact_sha:project.artifact_sha,evidence_ref:project.evidence_ref});var scoped=Object.assign({},data,{review:review});return'<div class="breadcrumb review-breadcrumb"><a href="#review">审核列表</a><span>/</span><a href="'+link('project',project.id)+'">项目详情</a><span>/</span><span>'+esc(page.id)+'</span></div>'+pageHead('项目预览与审核',project.name+' · 逐页绑定项目、版本、任务和证据。','<a class="button" href="'+link('project',project.id)+'">返回项目详情</a><a class="button" href="#review">返回审核列表</a>')+boundary()+'<div class="fact-grid trace-facts">'+fact('tenant_id',review.tenant_id)+fact('project_id',review.project_id)+fact('page_id',review.page_id)+fact('ui_version',review.ui_version)+fact('environment',review.environment)+fact('task_id',review.task_id)+fact('attempt_id',review.attempt_id)+fact('commit',review.commit)+fact('artifact_sha',review.artifact_sha)+fact('evidence_ref',review.evidence_ref)+'</div><div class="layers">'+review.layers.map(layer).join('')+'</div><section class="review-grid"><aside class="card review-panel"><div class="card-head"><h2>页面树</h2><span>'+pages.length+' 页</span></div>'+pageTree(project)+'</aside><section class="review-panel">'+syntheticPreview(Object.assign({},page,{version:version}))+'</section><aside class="card review-panel"><div class="tabs" role="tablist">'+[['feedback','反馈'],['diff','版本对比'],['evidence','证据']].map(function(t){return'<button class="tab" role="tab" aria-selected="'+(selectedTab===t[0])+'" data-tab="'+t[0]+'">'+t[1]+'</button>';}).join('')+'</div><div id="reviewTabPanel">'+reviewPanel(scoped)+'</div></aside></section><div class="mobile-review-actions" aria-label="移动审核动作"><a class="button" href="'+link('project',project.id)+'">返回项目</a><button class="button" data-demo-action="request-change">要求修改</button><button class="button primary" data-demo-action="submit-review">提交审核</button></div>';}
  function renderReviewSafe(data,r){if(!r.project_id)return renderReview(data,r);var project=data.projects.filter(function(p){return p.id===r.project_id;})[0];if(!project)return renderReview(data,r);if(r.page_id){var page=project.pages.filter(function(p){return p.id===r.page_id;})[0];if(!page)return pageHead('审核页面不存在','显式 page_id 未登记，已阻止审核且没有回退第一页。')+boundary()+'<div class="callout danger"><strong>UNKNOWN</strong><span>page_id '+esc(r.page_id)+' 未登记于 project_id '+esc(project.id)+'。</span></div><a class="button" href="#review">返回审核列表</a>';if(r.version&&r.version!==page.version)return pageHead('审核版本冲突','URL 版本与该页面已登记版本不一致，已阻止审核。')+boundary()+'<div class="callout danger"><strong>VERSION_CONFLICT</strong><span>请求 '+esc(r.version)+'；已登记 ui_version '+esc(page.version)+'。不得覆盖事实版本。</span></div><a class="button" href="#review">返回审核列表</a>';}else if(r.version){return pageHead('审核路由无效','version 不能脱离 page_id 使用，已阻止审核。')+boundary()+'<div class="callout danger"><strong>UNKNOWN</strong><span>page_id 缺失。</span></div><a class="button" href="#review">返回审核列表</a>';}return renderReview(data,r);}
  function renderReviewIsolated(data,r){if(r.project_id&&r.project_id!==data.review.project_id){var project=data.projects.filter(function(p){return p.id===r.project_id;})[0];if(project){data=Object.assign({},data,{review:Object.assign({},data.review,{feedback:[],evidence:[{kind:'项目证据',ref:project.evidence_ref||'NONE_FOUND',state:project.evidence_ref&&project.evidence_ref!=='NONE_FOUND'?'AVAILABLE':'NOT_CONNECTED'}]})});}}return renderReviewSafe(data,r);}
