  function platformSetup(config){var advanced=config.advanced||{},presets=advanced.provider_presets||[],saved=advanced.provider_onboarding||[],hosted=activeMode==='HOSTED_TEST_ONLY',cards=presets.map(function(p){var current=saved.filter(function(x){return x.platform===p.platform;})[0],openai=p.platform==='openai';return'<label class="card platform-setup-card"><input type="radio" name="providerPlatform" value="'+esc(p.platform)+'" '+(openai?'checked':'')+'><span><strong>'+esc(p.label)+'</strong><small class="mono">'+esc(p.platform)+' · '+esc(p.availability)+'</small><small>'+(current?'已保存 '+esc(current.connection_id)+' · '+esc(current.callable_state):'尚无已保存连接')+'</small></span></label>';}).join('')||'<div class="callout unknown"><strong>NONE_FOUND</strong><span>服务端未返回平台预设；不允许前端自填目标地址。</span></div>';return'<section class="model-platform-setup"><div class="card-head"><div><h2>平台接入</h2><p class="muted">沿既有固定平台预设测试、发现模型并保存；OpenAI 优先核验，但不假定已配置。</p></div>'+chip(config.status||'UNKNOWN')+'</div><div class="platform-choice-grid">'+cards+'</div><form id="providerSetupForm" autocomplete="off"><div class="short-step-grid"><label>连接名称<input name="connectionName" maxlength="64" placeholder="例如：团队主连接"></label><label>API Key<input name="credential" type="password" minlength="8" autocomplete="new-password" placeholder="仅提交服务端，不显示或保存到前端"></label><label>模型<select name="modelId"><option value="">先测试连接并读取模型</option></select></label></div><label class="paid-test-confirm"><input name="confirmPaidTest" type="checkbox"> 我确认“单次调用验证”最多发出 1 次请求、最多 2 个输出 token，可能产生上游费用。</label><div class="head-actions"><button class="button" type="button" data-provider-action="test-connection" '+(hosted?'':'disabled')+'>1. 测试连接 / 读取模型</button><button class="button" type="button" data-provider-action="test-model" '+(hosted?'':'disabled')+'>2. 单次调用验证</button><button class="button primary" type="submit" '+(hosted?'':'disabled')+'>3. 保存连接与模型</button></div><p id="providerSetupStatus" class="muted" aria-live="polite">'+(hosted?'尚未执行；真实调用验证会明确提示最多一次请求、最多 2 个输出 token。':'UI 候选 · 未连接服务端 · NOT_DEPLOYED')+'</p></form></section>';}
  function advancedModelTables(advanced){var connections=advanced.connections||[],models=advanced.models||[],assignments=advanced.assignments||[];function rows(values,fields){return values.length?values.map(function(x){return'<tr>'+fields.map(function(k){var value=k==='secret'?((x.secret||{}).state+' · '+(x.secret||{}).ref):x[k];return'<td>'+esc(value)+'</td>';}).join('')+'</tr>';}).join(''):'<tr><td colspan="'+fields.length+'">NONE_FOUND</td></tr>';}return'<details class="progressive-details admin-technical"><summary>连接、模型与任务绑定（高级）</summary><section class="card flush table-wrap"><h3 class="table-title">受保护连接</h3><table class="data-table"><thead><tr><th>连接</th><th>平台</th><th>用途</th><th>状态</th><th>SecretRef</th></tr></thead><tbody>'+rows(connections,['connection_id','provider_id','purpose','status','secret'])+'</tbody></table><h3 class="table-title">模型清单</h3><table class="data-table"><thead><tr><th>平台</th><th>模型</th><th>启用</th><th>价格状态</th></tr></thead><tbody>'+rows(models,['provider_id','model_id','enabled','price_state'])+'</tbody></table><h3 class="table-title">任务 / 项目绑定</h3><table class="data-table"><thead><tr><th>任务</th><th>角色</th><th>平台</th><th>模型</th><th>状态</th></tr></thead><tbody>'+rows(assignments,['task_id','role','provider_id','model_id','state'])+'</tbody></table></section></details>';}
  function renderHostedModels(data){var config=data.hosted_configuration||{records:[],status:'UNKNOWN'},advanced=config.advanced||{},usage=advanced.model_usage||[],providerTable='<section class="card flush table-wrap"><table class="data-table"><thead><tr><th>Provider</th><th>状态</th><th>价格状态</th><th>Secret</th><th>引用</th></tr></thead><tbody>'+(config.records.length?config.records.map(function(x){return'<tr><td>'+esc(x.display_name)+'<small class="mono">'+esc(x.provider_id)+'</small></td><td>'+esc(x.enabled?'ENABLED':'DISABLED')+'</td><td>'+esc(x.price_state)+'</td><td>'+esc(x.secret&&x.secret.state)+'</td><td class="mono">'+esc(x.secret&&x.secret.ref)+'</td></tr>';}).join(''):'<tr><td colspan="5">NONE_FOUND</td></tr>')+'</tbody></table></section>',usageTable='<section class="card flush table-wrap"><div class="callout unknown"><strong>MODEL ESTIMATE</strong><span>仅来自 ModelControl 用量事件与已配单价；不是财务账本、实际扣费或付款凭证，币种未知。</span></div><table class="data-table"><thead><tr><th>Provider / Model</th><th>请求数</th><th>Input / Output tokens</th><th>成本状态</th><th>估算值</th></tr></thead><tbody>'+(usage.length?usage.map(function(x){return'<tr><td>'+esc(x.provider_id)+'<small class="mono">'+esc(x.model_id)+'</small></td><td>'+esc(x.request_count)+'</td><td>'+esc(x.input_tokens)+' / '+esc(x.output_tokens)+'</td><td>'+esc(x.cost_state)+'</td><td>'+esc(x.estimated_cost)+' <small>'+esc(x.cost_unit)+'</small></td></tr>';}).join(''):'<tr><td colspan="5">NONE_FOUND</td></tr>')+'</tbody></table></section>';return pageHead('大模型','统一管理后台内配置多平台模型连接、模型清单与业务绑定；客户购买流程仍属于官网。')+boundary()+renderModelServiceAdminSummary(data)+platformSetup(config)+advancedModelTables(advanced)+'<details class="progressive-details admin-technical"><summary>Provider 与受保护引用</summary>'+providerTable+'</details><details class="progressive-details admin-technical"><summary>OpenAI 执行通道偏好</summary>'+renderChannelPreference(data,config)+'</details><details class="progressive-details admin-technical"><summary>模型用量与估算成本</summary>'+usageTable+'</details><section class="grid two-col"><article class="card"><h2>Capability</h2><div class="callout unknown"><strong>SERVER · BOUNDED ADMIN</strong><span>仅调用既有 ModelControl 动作；平台目标由服务端固定，身份、CSRF、凭据与测试回执均由服务端重验。</span></div></article>'+renderOperationLog({producer:'ModelControl'})+'</section>';}
  function renderDisconnectedConfiguration(data,kind,sourceKey,responsible){var source=(data.hosted_sources||{})[sourceKey]||{status:'NOT_CONNECTED',source_level:'UNKNOWN',source_candidates:[],evidence_refs:['NONE_FOUND'],gaps:['UNKNOWN']};return pageHead(kind,kind+'权威源未接入；不使用其他项目或历史数据填充。')+boundary()+'<section class="card"><div class="card-head"><h2>'+esc(kind)+'接线状态</h2>'+chip('NOT_CONNECTED')+'</div><div class="fact-grid">'+fact('status',source.status)+fact('source_level',source.source_level)+fact('responsible_party',responsible)+fact('allowed_actions','[]')+fact('source_candidates',(source.source_candidates||[]).join(' / ')||'NONE_FOUND')+fact('evidence_refs',(source.evidence_refs||[]).join(' / ')||'NONE_FOUND')+fact('gaps',(source.gaps||[]).join(' / ')||'UNKNOWN')+'</div><button class="button" disabled>无 capability</button></section>';}
