  function cookieValue(doc,name){var prefix=name+'=';return(doc.cookie||'').split(';').map(function(x){return x.trim();}).filter(function(x){return x.indexOf(prefix)===0;}).map(function(x){return decodeURIComponent(x.slice(prefix.length));})[0]||'';}
  function createHostedController(options){
    var generation=0,currentData=null;
    function refresh(reason){
      var requestGeneration=++generation;currentData=null;options.onLoading(reason);
      return options.fetch('../api/session',{credentials:'same-origin',cache:'no-store'}).then(function(session){
        if(requestGeneration!==generation)return{state:'STALE'};
        if(session.status===401){options.onLoginRequired();return{state:'LOGIN_REQUIRED'};}
        if(!session.ok)throw new Error('SESSION_HTTP_'+session.status);
        return options.fetch('../api/admin/workbench',{credentials:'same-origin',cache:'no-store'}).then(function(response){
          if(requestGeneration!==generation)return{state:'STALE'};
          if(!response.ok)throw new Error('HOSTED_HTTP_'+response.status);
          return response.json().then(function(value){
            if(requestGeneration!==generation)return{state:'STALE'};
            var projection=normalizeHostedProjection(value);
            return options.fetch('/customer/center/api/review_queue',{credentials:'same-origin',cache:'no-store'}).then(function(reviewResponse){return reviewResponse.ok?reviewResponse.json():null;}).catch(function(){return null;}).then(function(queue){if(requestGeneration!==generation)return{state:'STALE'};currentData=attachAuthoritativeReviewQueue(projection,queue);options.onData(currentData,reason);return{state:'READY',data:currentData};});
          });
        });
      }).catch(function(error){if(requestGeneration!==generation)return{state:'STALE'};currentData=null;options.onError(error,reason);return{state:'ERROR',error:error};});
    }
    return{refresh:refresh,current:function(){return currentData;},generation:function(){return generation;}};
  }
  function bootHosted(doc,win){
    var screen=doc.getElementById('loginScreen'),shell=doc.getElementById('shell'),bar=doc.querySelector('.candidate-bar'),logout=doc.getElementById('logoutButton'),side=doc.getElementById('sidebar'),scrim=doc.getElementById('scrim'),menu=doc.getElementById('menuButton'),refreshButton=doc.getElementById('refreshButton');
    screen.hidden=true;shell.hidden=false;bar.textContent='HOSTED · TEST_ONLY · 只读事实 + 受限模型配置';doc.getElementById('sidebarMode').textContent='TEST_ONLY 环境';doc.getElementById('sidebarSource').textContent='数据源：服务端投影 / ModelControl';doc.getElementById('profileLabel').textContent='TASK_CENTER_ADMIN';doc.getElementById('contextMode').textContent='SERVER · BOUNDED MODEL ADMIN';refreshButton.hidden=false;doc.querySelectorAll('[data-local-only]').forEach(function(node){node.hidden=true;});
    function closeMenu(returnFocus){var open=side.classList.contains('open');side.classList.remove('open');scrim.hidden=true;menu.setAttribute('aria-expanded','false');if(open&&returnFocus)menu.focus();}
    function openMenu(){side.classList.add('open');scrim.hidden=false;menu.setAttribute('aria-expanded','true');var first=side.querySelector('.nav-parent,.nav-child');if(first)first.focus();}
    menu.addEventListener('click',function(){if(side.classList.contains('open'))closeMenu(true);else openMenu();});scrim.addEventListener('click',function(){closeMenu(true);});side.addEventListener('click',function(e){if(e.target.closest('a'))closeMenu(false);});doc.addEventListener('keydown',function(e){if(e.key==='Escape'&&side.classList.contains('open')){e.preventDefault();closeMenu(true);}});
    function loading(reason){doc.getElementById('app').innerHTML=pageHead('正在读取','服务端 TEST_ONLY 只读投影。')+'<section class="card state-demo" aria-busy="true"><div class="skeleton"></div><div class="skeleton"></div><p class="muted">LOADING · '+esc(reason)+'</p></section>';}
    function failed(error){doc.getElementById('app').innerHTML=pageHead('读取失败','服务端投影不可用；没有保留或回退旧数据。')+'<div class="callout danger"><strong>HOSTED_PROJECTION_FAILED</strong><span>'+esc(error&&error.message||'UNKNOWN')+'</span></div><button class="button primary" id="retryHosted" type="button">重试读取</button>';doc.getElementById('retryHosted').addEventListener('click',function(){controller.refresh('RETRY');});}
    var controller=createHostedController({fetch:win.fetch.bind(win),onLoading:loading,onData:function(data){paint(doc,win,data);},onError:failed,onLoginRequired:function(){win.location.replace('../login.html?next='+encodeURIComponent(win.location.pathname+win.location.hash));}});
    win.__xjHostedRefresh=controller.refresh;
    win.__xjReviewApprove=function(payload){return win.fetch('/customer/center/api/review_approve',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':win.sessionStorage.getItem('xj_csrf')||''},body:JSON.stringify(payload)}).then(function(response){return response.json().catch(function(){return{};}).then(function(value){if(!response.ok)throw new Error(value.error||('REVIEW_APPROVE_HTTP_'+response.status));return value;});});};
    win.__xjModelAdminPost=function(payload){return win.fetch('../api/admin/model-control',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':cookieValue(doc,'task_center_csrf')},body:JSON.stringify(payload)}).then(function(response){return response.json().catch(function(){return{};}).then(function(value){if(!response.ok)throw new Error(value.error||('MODEL_CONTROL_HTTP_'+response.status));return value;});});};
    win.addEventListener('xj:set-channel-preference',function(e){var detail=e.detail||{};loading('SAVING_CHANNEL_PREFERENCE');win.fetch('../api/admin/model-control',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':cookieValue(doc,'task_center_csrf')},body:JSON.stringify({action:'SET_OPENAI_CHANNEL_PREFERENCE',preference:detail.preference,api_connection_id:detail.api_connection_id,oauth_connection_id:detail.oauth_connection_id,expected_version:detail.expected_version})}).then(function(response){if(!response.ok)throw new Error('CHANNEL_PREFERENCE_HTTP_'+response.status);return response.json();}).then(function(){return controller.refresh('CHANNEL_PREFERENCE_SAVED');}).catch(failed);});
    controller.refresh('INITIAL');win.addEventListener('hashchange',function(){closeMenu(false);controller.refresh('ROUTE_CHANGE');});refreshButton.addEventListener('click',function(){controller.refresh('MANUAL_REFRESH');});
    doc.getElementById('globalSearch').addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();win.location.hash='#projects';}});
    logout.textContent='退出登录';logout.addEventListener('click',function(){win.fetch('../api/session/logout',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':cookieValue(doc,'task_center_csrf')}}).then(function(){win.location.replace('../login.html');}).catch(failed);});
  }
  function boot(doc,win,data){
    if(win.location.protocol!=='file:')return bootHosted(doc,win);
    var form=doc.getElementById('loginForm'),screen=doc.getElementById('loginScreen'),shell=doc.getElementById('shell'),side=doc.getElementById('sidebar'),scrim=doc.getElementById('scrim'),menu=doc.getElementById('menuButton'),logout=doc.getElementById('logoutButton');
    doc.querySelector('.candidate-bar').textContent='UI_CANDIDATE · 合成数据 · 无生产写入 · 不连接真实服务';
    function sessionGet(){try{return win.sessionStorage.getItem('XJ_UI_CANDIDATE_SESSION')==='active';}catch(_error){return false;}}
    function sessionSet(active){try{if(active)win.sessionStorage.setItem('XJ_UI_CANDIDATE_SESSION','active');else win.sessionStorage.removeItem('XJ_UI_CANDIDATE_SESSION');}catch(_error){}var visibility=shellVisibility(active);screen.hidden=visibility.loginHidden;shell.hidden=visibility.shellHidden;if(active)paint(doc,win,data);}
    sessionSet(sessionGet());
    form.addEventListener('submit',function(e){e.preventDefault();form.elements.password.value='';sessionSet(true);announce(doc,'已进入合成工作台。此状态仅存于当前浏览器标签页。');});
    logout.addEventListener('click',function(){closeMenu();sessionSet(false);form.elements.password.value='';form.elements.username.focus();announce(doc,'已退出合成演示。');});
    function closeMenu(returnFocus){var wasOpen=side.classList.contains('open');side.classList.remove('open');scrim.hidden=true;menu.setAttribute('aria-expanded','false');if(returnFocus&&wasOpen)menu.focus();}
    function openMenu(){side.classList.add('open');scrim.hidden=false;menu.setAttribute('aria-expanded','true');var first=side.querySelector('.nav-parent,.nav-child');if(first)first.focus();}
    menu.addEventListener('click',function(){if(side.classList.contains('open'))closeMenu(true);else openMenu();});
    scrim.addEventListener('click',function(){closeMenu(true);});
    side.addEventListener('click',function(e){if(e.target.closest('a'))closeMenu(false);});
    doc.addEventListener('keydown',function(e){if(e.key==='Escape'&&side.classList.contains('open')){e.preventDefault();closeMenu(true);}});
    win.addEventListener('hashchange',function(){closeMenu(false);if(sessionGet())paint(doc,win,data);});
    doc.getElementById('profileButton').addEventListener('click',function(){announce(doc,'当前是 Owner 合成身份，不是生产登录。');});
    doc.getElementById('globalSearch').addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();win.location.hash='#projects';}});
  }
